package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.io.*;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.databind.ObjectCodec;
import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

/**
 * Unit tests for UTF8JsonGenerator.writeNumber(BigDecimal).
 * Aiming for maximum branch and line coverage.
 */
public class UTF8JsonGenerator_writeNumber_TriageGen2Test {

    private ByteArrayOutputStream outputStream;
    private IOContext ioContext;
    private ObjectCodec codec;
    private UTF8JsonGenerator generator;

    @Before
    public void setUp() {
        outputStream = new ByteArrayOutputStream();
        ioContext = IOContext.bootstrap();
        codec = Mockito.mock(ObjectCodec.class);
        // Using the constructor provided in the prompt
        generator = new UTF8JsonGenerator(ioContext, 0, codec, outputStream);
    }

    @Test
    public void testWriteNumber_NullValue() throws IOException {
        // Branch: if (value == null) -> _writeNull()
        generator.writeNumber((BigDecimal) null);

        // In Jackson, writeNull typically writes the literal 'null'
        assertEquals("null", outputStream.toString());
    }

    @Test
    public void testWriteNumber_WithNumbersAsStringConfigured() throws IOException {
        /* 
         * Branch: else if (_cfgNumbersAsStrings) { ; }
         * To test this branch, we need a generator where _cfgNumbersAsStrings is true.
         * Since we cannot easily set private fields via standard public API in a unit test 
         * without reflection, we simulate the behavior. 
         * However, in a real professional environment, we would use reflection 
         * to flip the private boolean flag.
         */

        // Using reflection to set _cfgNumbersAsStrings to true
        setPrivateField(generator, "_cfgNumbersAsStrings", true);

        BigDecimal value = new BigDecimal("123.45");
        generator.writeNumber(value);

        // If _cfgNumbersAsStrings is true, the method does nothing (empty block ';')
        // based on the provided source code logic.
        assertEquals("", outputStream.toString());
    }

    @Test
    public void testWriteNumber_StandardValue() throws IOException {
        /*
         * Branch: else { writeRaw(_asString(value)); }
         * This is the default path.
         */
        setPrivateField(generator, "_cfgNumbersAsStrings", false);

        BigDecimal value = new BigDecimal("123.45");
        generator.writeNumber(value);

        // Based on the code: writeRaw(_asString(value))
        // _asString(BigDecimal) typically returns "123.45"
        assertEquals("123.45", outputStream.toString());
    }

    @Test
    public void testWriteNumber_LargeBigDecimal() throws IOException {
        setPrivateField(generator, "_cfgNumbersAsStrings", false);

        BigDecimal value = new BigDecimal("1000000000000000000000.0000000001");
        generator.writeNumber(value);

        assertEquals("1000000000000000000000.0000000001", outputStream.toString());
    }

    /**
     * Helper method to access private fields for testing purposes.
     */
    private void setPrivateField(Object target, String fieldName, Object value) {
        try {
            java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(target, value);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
